package de.xrechnung.viewer;

import java.nio.file.*;
import java.util.*;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.text.PDFTextStripper;

/** Independent content and boundary contracts, not golden output generated by the renderer. */
public final class PdfTests {
  private static int passed;
  private static void ok(boolean value, String reason) { SemanticTests.check(value, reason); }
  private static String text(PdfInvoice.Snapshot pdf) throws Exception {
    try (var document = Loader.loadPDF(pdf.bytes())) { return new PDFTextStripper().getText(document); }
  }
  public static void main(String[] args) throws Exception {
    var file = InvoiceFile.open(Path.of("fixtures/Rechnora/rechnung-gemischte-steuersaetze2.xml"));
    byte[] before = file.originalBytes();
    var invoice = KositMapper.map(file);
    var pdf = PdfInvoice.create(file, invoice);
    String content = text(pdf);
    for (String expected : List.of("RE-2026-1", "149,80 EUR", "16,355 EUR", "19 %", "7 %", "pro Stück"))
      ok(content.contains(expected), "missing independent fixture expectation: " + expected);
    ok(Arrays.equals(before, file.originalBytes()), "input modified");
    var unknownSource = InvoiceFile.parse(new String(file.originalBytes(), java.nio.charset.StandardCharsets.UTF_8)
        .replace("H87", "QZZ").getBytes(java.nio.charset.StandardCharsets.UTF_8));
    String unknown = text(PdfInvoice.create(unknownSource,KositMapper.map(unknownSource)));
    ok(unknown.contains("pro 1 QZZ"), "unknown unit code was inferred or hidden");
    ok(content.contains("H87"), "original unit code missing from PDF details");
    ok(content.contains("Zahlbar innerhalb von 14 Tagen bis 2026-07-31."), "payment terms were silently rewritten");
    for(String base : List.of("1", "1.00", "+1")) {
      var source=InvoiceFile.parse(new String(file.originalBytes(),java.nio.charset.StandardCharsets.UTF_8)
          .replace(">1</ram:BasisQuantity>",">"+base+"</ram:BasisQuantity>").getBytes(java.nio.charset.StandardCharsets.UTF_8));
      ok(InvoicePresentation.price(KositMapper.map(source).root().all("BG-25").get(0),"EUR").endsWith("pro Stück"), "one-piece basis not abbreviated");
    }
    var hundred=InvoiceFile.parse(new String(file.originalBytes(),java.nio.charset.StandardCharsets.UTF_8)
        .replace(">1</ram:BasisQuantity>",">100</ram:BasisQuantity>").getBytes(java.nio.charset.StandardCharsets.UTF_8));
    ok(InvoicePresentation.price(KositMapper.map(hundred).root().all("BG-25").get(0),"EUR").endsWith("pro 100 Stück"), "non-unit basis hidden");
    passed++; System.out.println("PASS PDF retains provided amounts, precision, price bases and tax rates");

    try (var doc = Loader.loadPDF(pdf.bytes())) {
      var second = new PDFTextStripper(); second.setStartPage(2); second.setEndPage(2);
      ok(second.getText(doc).contains("Original-SHA-256:"), "orphaned summary note occupies its own page");
    }
    passed++; System.out.println("PASS detail appendix begins without an orphaned transition page");

    var rc = InvoiceFile.open(Path.of("fixtures/Rechnora/rechnung-reverse-charge.xml"));
    var reverse = KositMapper.map(rc);
    String reverseText = text(PdfInvoice.create(rc, reverse));
    for (var node : reverse.root().all("BT-120")) ok(reverseText.contains(node.value()), "exemption reason absent");
    ok(reverseText.contains("AE"), "reverse-charge category absent");
    try (var doc = Loader.loadPDF(PdfInvoice.create(rc, reverse).bytes())) {
      var second = new PDFTextStripper(); second.setStartPage(2); second.setEndPage(2);
      ok(second.getText(doc).contains("Original-SHA-256:"), "payment line orphaned onto a separate summary page");
    }
    passed++; System.out.println("PASS reverse-charge information is present");

    var originalDemo = InvoiceFile.open(Path.of("fixtures/demo-paper-with-gap.xml"));
    var originalModel = KositMapper.map(originalDemo);
    String readable = text(PdfInvoice.create(originalDemo, originalModel)).replaceAll("\\s+", " ");
    ok(readable.contains("Zeitschrift [...]"), "long original line identifier missing");
    ok(readable.contains("Porto + Versandkosten"), "second long identifier not preserved");
    ok(!readable.contains("Pos.-ID:"), "identifier still moved into description");
    try (var doc = Loader.loadPDF(PdfInvoice.create(originalDemo, originalModel).bytes())) {
      var area = new org.apache.pdfbox.text.PDFTextStripperByArea();
      area.addRegion("identifiers",new java.awt.geom.Rectangle2D.Float(56,300,100,280));
      area.extractRegions(doc.getPage(0));
      String identifiers=area.getTextForRegion("identifiers").replaceAll("\\s+"," ");
      ok(identifiers.contains("Zeitschrift [...]"),"identifier absent from its column");
      ok(identifiers.contains("Porto + Versandkosten"),"second identifier absent from its column");
    }
    ok(originalModel.root().all("BG-25").get(0).value("BT-126").equals("Zeitschrift [...]"), "identifier renumbered");
    passed++; System.out.println("PASS long source line identifiers remain readable without invented numbering");

    var demo = InvoiceFile.open(Path.of("fixtures/demo-darstellungshinweise.xml"));
    var mapped = KositMapper.map(demo);
    String diagnostic = text(PdfInvoice.create(demo, mapped));
    ok(diagnostic.contains("Diagnoseanhang"), "no diagnostic appendix");
    ok(diagnostic.contains("Ende des vollständigen Quellwerts.</html>"), "long literal value lost");
    for (var gap : mapped.gaps()) {
      ok(diagnostic.replaceAll("\\s", "").contains(gap.sourcePath().replaceAll("\\s", "")), "exact gap origin missing");
      ok(diagnostic.contains(gap.reason()), "gap reason absent");
    }
    passed++; System.out.println("PASS full diagnostics retain origins, reasons, long and empty values");

    var fields = new ArrayList<SemanticInvoice.Node>();
    for (var d : FieldCatalog.definitions()) if (d.id().startsWith("BT-"))
      fields.add(new SemanticInvoice.Node(d.id(), d.name(), d.id(), d.label(),
          "VALUE-"+d.id()+"-END", "/source", d.type(),
          List.of(new SemanticInvoice.Property("scheme_identifier", "Kennungsschema", "SCHEME-"+d.id()+"-END")), List.of()));
    var root = new SemanticInvoice.Node("root", "invoice", "", "Rechnung", "", "", "", List.of(), fields);
    String complete = text(PdfInvoice.create(file, new SemanticInvoice(root, List.of(), "Nicht validiert")));
    for (var field : fields) {
      ok(complete.contains(field.value()), "field lost: " + field.id());
      ok(complete.contains(field.properties().get(0).value()), "property lost: " + field.id());
    }
    passed++; System.out.println("PASS all 167 modeled terms and their metadata reach the PDF");

    var lines = new ArrayList<SemanticInvoice.Node>();
    var sample = invoice.root().all("BG-25").get(0);
    for (int i=0; i<45; i++) lines.add(new SemanticInvoice.Node("line"+i, sample.name(), sample.id(),sample.label(), "", sample.sourcePath(),sample.type(), sample.properties(),sample.children()));
    var multi = PdfInvoice.create(file, new SemanticInvoice(new SemanticInvoice.Node("0","invoice","","Rechnung","","","",List.of(),lines),List.of(),"Nicht validiert"));
    try (var doc = Loader.loadPDF(multi.bytes())) {
      ok(doc.getNumberOfPages()>3, "multi-page case did not paginate");
      for (int i=1; i<=doc.getNumberOfPages(); i++) {
        var stripper = new PDFTextStripper(); stripper.setStartPage(i); stripper.setEndPage(i);
        String page = stripper.getText(doc);
        ok(page.contains("Spezifikationstreue nicht zertifiziert"), "missing page disclaimer");
        ok(page.contains("Ziel:") && page.contains("EN 16931-1") && page.contains("DIN 5008"), "product goal missing beside disclaimer");
        ok(page.contains("Seite " + i + " / " + doc.getNumberOfPages()), "wrong page number");
      }
      String all = text(multi);
      ok(all.indexOf("Einzelpreis") != all.lastIndexOf("Einzelpreis"), "table header not repeated");
    }
    passed++; System.out.println("PASS long tables paginate with repeated headings and per-page disclaimers");

    // Replace existing item-name fields, including nested ones, with one independently long value.
    var huge = new SemanticInvoice.Node("huge","INVOICE_LINE","BG-25","Rechnungsposition","","","",List.of(),
        List.of(new SemanticInvoice.Node("description","Item_name","BT-153","Artikelname",
            "LANGE-POSITION ".repeat(1200)+"ENDE-DER-POSITION", "/source", "xr:text",List.of(),List.of())));
    var tall = PdfInvoice.create(file,new SemanticInvoice(new SemanticInvoice.Node("0","invoice","","Rechnung","","","",List.of(),List.of(huge)),List.of(),"Nicht validiert"));
    ok(text(tall).contains("ENDE-DER-POSITION"), "oversized row tail lost");
    passed++; System.out.println("PASS a single oversized table row continues without truncation");
    for (var checked : List.of(pdf, multi, tall)) {
      try(var doc=Loader.loadPDF(checked.bytes())) {
        new PDFTextStripper() {
          @Override protected void processTextPosition(org.apache.pdfbox.text.TextPosition pos) {
            ok(pos.getXDirAdj() >= 55, "text escaped left margin");
            ok(pos.getXDirAdj()+pos.getWidthDirAdj() <= 554, "text escaped right margin");
            ok(pos.getYDirAdj() >= 25 && pos.getYDirAdj() < 830, "text escaped vertical page bounds");
            super.processTextPosition(pos);
          }
        }.getText(doc);
      }
    }
    passed++; System.out.println("PASS text stays inside page bounds across summary, details and long rows");

    byte[] bytes = pdf.bytes(); bytes[0]=0;
    ok(pdf.bytes()[0]=='%', "snapshot bytes are mutable");
    Path dir = Files.createTempDirectory(Path.of("build"),"pdf-contract-");
    try {
      Path out = dir.resolve("invoice.pdf"); pdf.save(out);
      ok(Arrays.equals(pdf.bytes(),Files.readAllBytes(out)), "export differs from preview bytes");
      try { pdf.save(out); throw new AssertionError("overwrote existing PDF"); } catch (FileAlreadyExistsException expected) { }
      ok(Arrays.equals(pdf.bytes(), Files.readAllBytes(out)), "existing target changed");
      ok(pdf.renderPage(0, 72).getWidth()>500, "preview did not render snapshot");
      Files.delete(out);
    } finally { Files.delete(dir); }
    passed++; System.out.println("PASS immutable snapshot, exact export, no overwrite and preview rendering");

    var previousZone=java.util.TimeZone.getDefault();
    try {
      String originalText=new String(SemanticTests.minimal("").originalBytes(),java.nio.charset.StandardCharsets.UTF_8);
      for(String zone:List.of("Pacific/Kiritimati","America/Los_Angeles")) {
        java.util.TimeZone.setDefault(java.util.TimeZone.getTimeZone(zone));
        for(String value:List.of("2026-11-09T00:30:00+14:00","2026-11-09T23:30:00-12:00","2026-11-09T02:30:00")) {
          var timeSource=InvoiceFile.parse(originalText.replace("2026-11-08",value).getBytes(java.nio.charset.StandardCharsets.UTF_8));
          String timePdf=text(PdfInvoice.create(timeSource,KositMapper.map(timeSource)));
          ok(timePdf.contains(value),"PDF lost source time or offset");
          ok(timePdf.contains("Kein gültiges reines Kalenderdatum"),"PDF omitted date warning");
        }
      }
    } finally { java.util.TimeZone.setDefault(previousZone); }
    passed++; System.out.println("PASS PDF retains source times and offsets across system zones with diagnostics");

    var bad = new SemanticInvoice.Node("bad","Invoice_note","BT-22","Bemerkung","unsupported: \uD83D\uDE00","/source","xr:text",List.of(),List.of());
    try {
      PdfInvoice.create(file, new SemanticInvoice(new SemanticInvoice.Node("0","invoice","","Rechnung","","","",List.of(),List.of(bad)),List.of(),"Nicht validiert"));
      throw new AssertionError("unsupported glyph silently lost");
    } catch (java.io.IOException expected) { ok(expected.getMessage().contains("Zeichen"), "no understandable glyph error"); }
    passed++; System.out.println("PASS unsupported glyphs fail explicitly instead of silently disappearing");
    System.out.println("RESULT: " + passed + " PDF contracts passed");
  }
}
